//! Bit-exact replay of the ten `pawn_native_ai` entry points against the
//! oracle records in `fixtures/pawn_native_ai.txt` (generated by
//! `Build/pawn_native_ai_fixture_harness/gen_pawn_native_ai.sh`).
//!
//! Each record carries the input world, the call arguments, the return and
//! values, the post-call world, and the ordered list of service hook
//! calls the oracle made. The mocks below replay those hook outputs in order
//! and assert the Rust side makes exactly the same calls.

use hp2_abi::FVector;
use hp2_abi::engine::generated::{AActor, APlayerPawn, FCheckResult, FRotator};
use hp2_engine::pawn_native_ai::{
    Hp2PawnNativeAiServices, add_pawn, find_stair_rotation, pick_any_target, pick_target,
    player_can_see_me, poll_wait_for_landing, remove_pawn, stop_waiting, test_can_see_me,
    wait_for_landing,
};
use std::cell::RefCell;
use std::ffi::c_void;
use std::sync::LazyLock;

const FIXTURE: &str = include_str!("fixtures/pawn_native_ai.txt");

// World layout, mirroring the harness: pawns 1..=6, actors 7..=10, level 11, PRIs 12..=13.
const PAWNS: usize = 6;
const ACTORS: usize = 4;
const PRIS: usize = 2;
const PAWN_WORDS: usize = 16;
const ACTOR_WORDS: usize = 3;
const WORLD_WORDS: usize = PAWNS * PAWN_WORDS + ACTORS * ACTOR_WORDS;
const LEVEL_ID: usize = PAWNS + ACTORS + 1;
const KINDS: usize = 21;

// Hook kinds, one per `Hp2PawnNativeAiServices` field (harness enum order).
const K_ROTATION_VECTOR: u32 = 1;
const K_STATE_LATENT_ACTION: u32 = 2;
const K_SET_STATE_LATENT_ACTION: u32 = 3;
const K_LEVEL_NET_MODE: u32 = 4;
const K_LEVEL_PAWN_LIST: u32 = 5;
const K_SET_LEVEL_PAWN_LIST: u32 = 6;
const K_LEVEL_TEAM_GAME: u32 = 7;
const K_LEVEL_ACTOR_COUNT: u32 = 8;
const K_LEVEL_ACTOR: u32 = 9;
const K_VIEWPORT_COUNT: u32 = 10;
const K_VIEWPORT_ACTOR: u32 = 11;
const K_ACTOR_NET_TEMPORARY: u32 = 12;
const K_ACTOR_PROJ_TARGET: u32 = 13;
const K_ACTOR_IS_PAWN: u32 = 14;
const K_PAWN_HEALTH: u32 = 15;
const K_PAWN_BEHIND_VIEW: u32 = 16;
const K_REPLICATION_TEAM: u32 = 17;
const K_LINE_OF_SIGHT_TO: u32 = 18;
const K_SINGLE_LINE_CHECK: u32 = 19;
const K_EVENT_LONG_FALL: u32 = 20;

#[derive(Clone)]
struct Script {
    kind: u32,
    args: Vec<u32>,
    outs: Vec<u32>,
}

#[derive(Clone)]
struct Record {
    name: String,
    _case: u32,
    world: Vec<u32>,
    args: Vec<u32>,
    ret: Vec<u32>,
    outs: Vec<u32>,
    post: Vec<u32>,
    scripts: Vec<Script>,
}

/// `(args, ret, outs)` word counts per entry point.
fn arity(name: &str) -> (usize, usize, usize) {
    match name {
        "player_can_see_me" => (1, 1, 0),
        "test_can_see_me" => (2, 1, 0),
        "pick_target" | "pick_any_target" => (9, 1, 2),
        "add_pawn" | "remove_pawn" | "stop_waiting" | "wait_for_landing" => (1, 0, 0),
        "poll_wait_for_landing" => (2, 0, 0),
        "find_stair_rotation" => (2, 1, 0),
        other => panic!("unknown entry {other}"),
    }
}

fn parse_line(line: &str) -> Record {
    let mut tokens = line.split_whitespace();
    let name = tokens.next().expect("record name").to_string();
    let words: Vec<u32> = tokens
        .map(|w| u32::from_str_radix(w, 16).expect("hex word"))
        .collect();
    let (nargs, nret, nouts) = arity(&name);
    let mut at = 0;
    let mut take = |n: usize| {
        let s = words[at..at + n].to_vec();
        at += n;
        s
    };
    let case = take(1)[0];
    let world = take(WORLD_WORDS);
    let args = take(nargs);
    let ret = take(nret);
    let outs = take(nouts);
    let post = take(WORLD_WORDS);
    let nlog = take(1)[0];
    let mut scripts = Vec::with_capacity(nlog as usize);
    for _ in 0..nlog {
        let kind = take(1)[0];
        let argc = take(1)[0] as usize;
        let args = take(argc);
        let outc = take(1)[0] as usize;
        let outs = take(outc);
        scripts.push(Script { kind, args, outs });
    }
    assert_eq!(at, words.len(), "{name}: trailing words");
    Record {
        name,
        _case: case,
        world,
        args,
        ret,
        outs,
        post,
        scripts,
    }
}

static RECORDS: LazyLock<Vec<Record>> = LazyLock::new(|| FIXTURE.lines().map(parse_line).collect());

#[derive(Default)]
struct Replay {
    scripts: Vec<Script>,
    at: usize,
    /// `ptrs[id]` is the address of object `id`; `ptrs[0]` is null.
    ptrs: Vec<usize>,
}

thread_local! {
    static REPLAY: RefCell<Replay> = RefCell::new(Replay::default());
    static HITS: RefCell<[usize; KINDS]> = const { RefCell::new([0; KINDS]) };
}

/// Pops the next scripted hook, asserting it is the call the Rust side just made.
fn take(kind: u32, args: &[u32]) -> Vec<u32> {
    HITS.with(|h| h.borrow_mut()[kind as usize] += 1);
    REPLAY.with(|r| {
        let mut r = r.borrow_mut();
        let at = r.at;
        let s = r
            .scripts
            .get(at)
            .unwrap_or_else(|| panic!("unexpected hook kind {kind} at {at}"));
        assert_eq!(s.kind, kind, "hook #{at} kind");
        assert_eq!(s.args, args, "hook #{at} (kind {kind}) args");
        let outs = s.outs.clone();
        r.at = at + 1;
        outs
    })
}

fn pid(p: *const c_void) -> u32 {
    if p.is_null() {
        return 0;
    }
    REPLAY.with(|r| {
        r.borrow()
            .ptrs
            .iter()
            .skip(1)
            .position(|&q| q == p as usize)
            .map(|i| i as u32 + 1)
            .unwrap_or_else(|| panic!("unknown object {p:?}"))
    })
}

fn ptr_at(id: u32) -> *mut c_void {
    REPLAY.with(|r| r.borrow().ptrs[id as usize] as *mut c_void)
}

fn fw(v: f32) -> u32 {
    v.to_bits()
}

fn vwords(v: FVector) -> [u32; 3] {
    [fw(v.x), fw(v.y), fw(v.z)]
}

fn vec3(w: &[u32]) -> FVector {
    FVector {
        x: f32::from_bits(w[0]),
        y: f32::from_bits(w[1]),
        z: f32::from_bits(w[2]),
    }
}

// --- Hook mocks. Each mirrors one `Hp2PawnNativeAiServices` field exactly. ---

unsafe extern "C" fn rotation_vector(rot: *const c_void, out: *mut c_void) {
    unsafe {
        let r = &*rot.cast::<FRotator>();
        let o = take(
            K_ROTATION_VECTOR,
            &[r.pitch as u32, r.yaw as u32, r.roll as u32],
        );
        *out.cast::<FVector>() = vec3(&o);
    }
}

unsafe extern "C" fn state_latent_action(actor: *mut c_void) -> i32 {
    take(K_STATE_LATENT_ACTION, &[pid(actor)])[0] as i32
}

unsafe extern "C" fn set_state_latent_action(actor: *mut c_void, action: i32) {
    assert!(take(K_SET_STATE_LATENT_ACTION, &[pid(actor), action as u32]).is_empty());
}

unsafe extern "C" fn level_net_mode(level: *mut c_void) -> i32 {
    take(K_LEVEL_NET_MODE, &[pid(level)])[0] as i32
}

unsafe extern "C" fn level_pawn_list(level: *mut c_void) -> *mut c_void {
    ptr_at(take(K_LEVEL_PAWN_LIST, &[pid(level)])[0])
}

unsafe extern "C" fn set_level_pawn_list(level: *mut c_void, pawn: *mut c_void) {
    assert!(take(K_SET_LEVEL_PAWN_LIST, &[pid(level), pid(pawn)]).is_empty());
}

unsafe extern "C" fn level_team_game(level: *mut c_void) -> i32 {
    take(K_LEVEL_TEAM_GAME, &[pid(level)])[0] as i32
}

unsafe extern "C" fn level_actor_count(level: *mut c_void) -> i32 {
    take(K_LEVEL_ACTOR_COUNT, &[pid(level)])[0] as i32
}

unsafe extern "C" fn level_actor(level: *mut c_void, index: i32) -> *mut c_void {
    ptr_at(take(K_LEVEL_ACTOR, &[pid(level), index as u32])[0])
}

unsafe extern "C" fn viewport_count(level: *mut c_void) -> i32 {
    take(K_VIEWPORT_COUNT, &[pid(level)])[0] as i32
}

unsafe extern "C" fn viewport_actor(level: *mut c_void, index: i32) -> *mut c_void {
    ptr_at(take(K_VIEWPORT_ACTOR, &[pid(level), index as u32])[0])
}

unsafe extern "C" fn actor_net_temporary(actor: *mut c_void) -> i32 {
    take(K_ACTOR_NET_TEMPORARY, &[pid(actor)])[0] as i32
}

unsafe extern "C" fn actor_proj_target(actor: *mut c_void) -> i32 {
    take(K_ACTOR_PROJ_TARGET, &[pid(actor)])[0] as i32
}

unsafe extern "C" fn actor_is_pawn(actor: *mut c_void) -> i32 {
    take(K_ACTOR_IS_PAWN, &[pid(actor)])[0] as i32
}

unsafe extern "C" fn pawn_health(pawn: *mut c_void) -> i32 {
    take(K_PAWN_HEALTH, &[pid(pawn)])[0] as i32
}

unsafe extern "C" fn pawn_behind_view(pawn: *mut c_void) -> i32 {
    take(K_PAWN_BEHIND_VIEW, &[pid(pawn)])[0] as i32
}

unsafe extern "C" fn replication_team(info: *mut c_void) -> i32 {
    take(K_REPLICATION_TEAM, &[pid(info)])[0] as i32
}

unsafe extern "C" fn line_of_sight_to(pawn: *mut c_void, other: *mut c_void) -> i32 {
    take(K_LINE_OF_SIGHT_TO, &[pid(pawn), pid(other)])[0] as i32
}

unsafe extern "C" fn single_line_check(
    level: *mut c_void,
    source: *mut c_void,
    hit: *mut c_void,
    end: *const c_void,
    start: *const c_void,
    trace: u32,
    extent: *const c_void,
) {
    unsafe {
        let end = *end.cast::<FVector>();
        let start = *start.cast::<FVector>();
        let extent = *extent.cast::<FVector>();
        let mut args = vec![pid(level), pid(source)];
        args.extend(vwords(end));
        args.extend(vwords(start));
        args.push(trace);
        args.extend(vwords(extent));
        let o = take(K_SINGLE_LINE_CHECK, &args);
        let hit = &mut *hit.cast::<FCheckResult>();
        hit.time = f32::from_bits(o[0]);
        hit.normal = vec3(&o[1..4]);
    }
}

unsafe extern "C" fn event_long_fall(pawn: *mut c_void) {
    assert!(take(K_EVENT_LONG_FALL, &[pid(pawn)]).is_empty());
}

const SVC: Hp2PawnNativeAiServices = Hp2PawnNativeAiServices {
    rotation_vector,
    state_latent_action,
    set_state_latent_action,
    level_net_mode,
    level_pawn_list,
    set_level_pawn_list,
    level_team_game,
    level_actor_count,
    level_actor,
    viewport_count,
    viewport_actor,
    actor_net_temporary,
    actor_proj_target,
    actor_is_pawn,
    pawn_health,
    pawn_behind_view,
    replication_team,
    line_of_sight_to,
    single_line_check,
    event_long_fall,
};

// --- World model: owned storage whose addresses are the object ids. ---

struct World {
    pawns: Vec<APlayerPawn>,
    actors: Vec<AActor>,
    level: Box<u64>,
    pris: Vec<u64>,
}

impl World {
    fn new(w: &[u32]) -> World {
        let mut world = World {
            pawns: (0..PAWNS).map(|_| unsafe { std::mem::zeroed() }).collect(),
            actors: (0..ACTORS).map(|_| unsafe { std::mem::zeroed() }).collect(),
            level: Box::new(0),
            pris: vec![0; PRIS],
        };
        let ids = world.ids();
        let level = ids[LEVEL_ID] as *mut c_void;
        for (i, p) in world.pawns.iter_mut().enumerate() {
            let o = &w[i * PAWN_WORDS..(i + 1) * PAWN_WORDS];
            p.base.base.location = vec3(&o[0..3]);
            p.base.base.collision_radius = f32::from_bits(o[3]);
            p.base.base.collision_height = f32::from_bits(o[4]);
            p.base.base.latent_float = f32::from_bits(o[5]);
            p.base.base.physics = o[6] as u8;
            p.base.base.role = o[7] as u8;
            p.base.base.x_level = ptr_of(&ids, o[8]);
            p.base.next_pawn = ptr_of(&ids, o[9]);
            p.base.player_replication_info = ptr_of(&ids, o[10]);
            p.view_target = ptr_of(&ids, o[11]);
            p.base.view_rotation = FRotator {
                pitch: o[12] as i32,
                yaw: o[13] as i32,
                roll: o[14] as i32,
            };
            p.base.base_eye_height = f32::from_bits(o[15]);
        }
        for (j, a) in world.actors.iter_mut().enumerate() {
            let o = &w[PAWNS * PAWN_WORDS + j * ACTOR_WORDS..][..ACTOR_WORDS];
            a.location = vec3(o);
            a.x_level = level;
        }
        world
    }

    /// Object addresses indexed by id; `0` is null.
    fn ids(&self) -> Vec<usize> {
        let mut ids = vec![0];
        ids.extend(self.pawns.iter().map(|p| p as *const _ as usize));
        ids.extend(self.actors.iter().map(|a| a as *const _ as usize));
        ids.push(&*self.level as *const u64 as usize);
        ids.extend(self.pris.iter().map(|p| p as *const u64 as usize));
        ids
    }

    fn pack(&self, ids: &[usize]) -> Vec<u32> {
        let mut out = Vec::with_capacity(WORLD_WORDS);
        for p in &self.pawns {
            out.extend(vwords(p.base.base.location));
            out.push(fw(p.base.base.collision_radius));
            out.push(fw(p.base.base.collision_height));
            out.push(fw(p.base.base.latent_float));
            out.push(p.base.base.physics as u32);
            out.push(p.base.base.role as u32);
            out.push(id_of(ids, p.base.base.x_level));
            out.push(id_of(ids, p.base.next_pawn));
            out.push(id_of(ids, p.base.player_replication_info));
            out.push(id_of(ids, p.view_target));
            out.push(p.base.view_rotation.pitch as u32);
            out.push(p.base.view_rotation.yaw as u32);
            out.push(p.base.view_rotation.roll as u32);
            out.push(fw(p.base.base_eye_height));
        }
        for a in &self.actors {
            out.extend(vwords(a.location));
        }
        out
    }
}

fn ptr_of(ids: &[usize], id: u32) -> *mut c_void {
    ids[id as usize] as *mut c_void
}

fn id_of(ids: &[usize], p: *mut c_void) -> u32 {
    if p.is_null() {
        return 0;
    }
    ids.iter()
        .skip(1)
        .position(|&q| q == p as usize)
        .map(|i| i as u32 + 1)
        .unwrap_or_else(|| panic!("unknown object {p:?}"))
}

fn run_record(rec: &Record) {
    let world = World::new(&rec.world);
    let ids = world.ids();
    assert_eq!(
        world.pack(&ids),
        rec.world,
        "{}: world round-trip",
        rec.name
    );
    REPLAY.with(|r| {
        let mut r = r.borrow_mut();
        r.scripts = rec.scripts.clone();
        r.at = 0;
        r.ptrs = ids.clone();
    });
    let a = &rec.args;
    let pawn = ptr_of(&ids, a[0]);
    match rec.name.as_str() {
        "player_can_see_me" => {
            let got = unsafe { player_can_see_me(&SVC, pawn.cast()) };
            assert_eq!(rec.ret, vec![got as u32], "{}: ret", rec.name);
            assert!(rec.outs.is_empty());
        }
        "test_can_see_me" => {
            let got = unsafe {
                test_can_see_me(&SVC, ptr_of(&ids, a[0]).cast(), ptr_of(&ids, a[1]).cast())
            };
            assert_eq!(rec.ret, vec![got as u32], "{}: ret", rec.name);
            assert!(rec.outs.is_empty());
        }
        "pick_target" | "pick_any_target" => {
            let mut aim = f32::from_bits(a[1]);
            let mut dist = f32::from_bits(a[2]);
            let fire = vec3(&a[3..6]);
            let start = vec3(&a[6..9]);
            let picked = unsafe {
                if rec.name == "pick_target" {
                    pick_target(&SVC, pawn.cast(), &mut aim, &mut dist, fire, start).cast()
                } else {
                    pick_any_target(&SVC, pawn.cast(), &mut aim, &mut dist, fire, start).cast()
                }
            };
            assert_eq!(rec.ret, vec![pid(picked)], "{}: picked", rec.name);
            assert_eq!(
                rec.outs,
                vec![aim.to_bits(), dist.to_bits()],
                "{}: best aim/dist",
                rec.name
            );
        }
        "add_pawn" => unsafe { add_pawn(&SVC, pawn.cast()) },
        "remove_pawn" => unsafe { remove_pawn(&SVC, pawn.cast()) },
        "stop_waiting" => unsafe { stop_waiting(&SVC, pawn.cast()) },
        "wait_for_landing" => unsafe { wait_for_landing(&SVC, pawn.cast()) },
        "poll_wait_for_landing" => {
            let delta = f32::from_bits(a[1]);
            unsafe { poll_wait_for_landing(&SVC, pawn.cast(), &delta) };
        }
        "find_stair_rotation" => {
            let delta = f32::from_bits(a[1]);
            let mut hit: FCheckResult = unsafe { std::mem::zeroed() };
            hit.time = 1.0;
            let got = unsafe { find_stair_rotation(&SVC, pawn.cast(), delta, &mut hit) };
            assert_eq!(rec.ret, vec![got as u32], "{}: stair", rec.name);
        }
        other => panic!("unknown entry {other}"),
    }
    REPLAY.with(|r| {
        assert_eq!(
            r.borrow().at,
            rec.scripts.len(),
            "{}: unconsumed hooks",
            rec.name
        )
    });
    assert_eq!(
        world.pack(&ids),
        rec.post,
        "{} case {:08x}: post-call world",
        rec.name,
        rec._case
    );
}

/// Replays every record for `entry` and checks each hook kind was hit exactly
/// as often as the oracle logged it. Returns the record count.
fn replay_entry(entry: &str) -> usize {
    let mut count = 0;
    let mut expected = [0usize; KINDS];
    for rec in RECORDS.iter().filter(|r| r.name == entry) {
        count += 1;
        for s in &rec.scripts {
            expected[s.kind as usize] += 1;
        }
        run_record(rec);
    }
    HITS.with(|h| assert_eq!(*h.borrow(), expected, "{entry}: hook hits"));
    count
}

#[test]
fn player_can_see_me_replays() {
    assert_eq!(replay_entry("player_can_see_me"), 24);
}

